func runReview(ctx context.Context, cmd *cobra.Command, agentOverride string, deps runReviewDeps) error {
	out := cmd.OutOrStdout()

	// 1. Pre-flight: must be in a git repo.
	if _, err := paths.WorktreeRoot(ctx); err != nil {
